/**
 * activator.js — Step 4 of docs/scale-to-zero-gated-plan.md.
 *
 * Catches a request for an app that scale-to-zero has stopped, starts it
 * back up, waits for it to be reachable, and forwards the ORIGINAL
 * request through — so the visitor sees a slow response, never an error.
 *
 * How the request gets here at all: app routers are generated by
 * Traefik's Nomad provider from RUNNING services, so a stopped app has no
 * router and its hostname would 404. /opt/traefik/dynamic.yml declares a
 * per-app fallback router with `priority: 1` pointing at this process.
 * Traefik picks the highest-priority matching router and app routers set
 * no explicit priority, which means Traefik defaults theirs to the rule's
 * length (~44 for a Host rule) — far above 1. So while the app runs,
 * traffic goes straight to it and never touches this process; the instant
 * the job stops and its router disappears, the fallback is the only match
 * left. No traffic for any other app can reach here, because a fallback
 * router only exists for hostnames explicitly listed in that file.
 *
 * A SEPARATE pm2 process, not an endpoint inside deploy-service: this
 * sits in the request path of real visitor traffic and holds connections
 * open for the length of a cold start. If it wedges or dies, it must take
 * deploy-service's API down with it — and Step 4's checklist asks us to
 * prove no other app's traffic passes through this component, which is
 * far easier to argue about a process that serves nothing else.
 *
 *   node activator.js
 */
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '.env') });

const http = require('http');
const fsp = require('fs/promises');
const { execFile } = require('child_process');
const { promisify } = require('util');
const execFileAsync = promisify(execFile);

const { appDataPathFor, defaultDomainFor } = require('./nomad-job-spec');
const { imagesFromSpec, missingImages } = require('./scale-to-zero-images');

const NOMAD_ADDR = process.env.NOMAD_ADDR || 'http://127.0.0.1:4646';
const PORT = Number(process.env.ACTIVATOR_PORT) || 4200;

// THE SAFETY RAIL, and deliberately the same shape as idle-report.js's
// STOPPABLE_APPS: hardcoded and frozen, so widening it is a reviewed code
// change rather than a config edit. These two lists must agree — an app
// that can be stopped but not woken is an app we have taken offline
// permanently. Step 6 is where both grow together.
const WAKEABLE_APPS = Object.freeze(['scale-to-zero-test-1']);

// How long to hold a visitor's request while the app cold-starts before
// giving up. A container pull is already local (force_pull = false), so
// this is mostly image start + the app's own boot.
const WAKE_TIMEOUT_MS = Number(process.env.WAKE_TIMEOUT_MS) || 90000;

// Requests arriving during a cold start have their body buffered so it
// can be replayed once the app is up. Capped rather than unbounded: this
// process must not be turned into a memory sink by a large upload aimed
// at a sleeping app.
const MAX_BODY_BYTES = Number(process.env.ACTIVATOR_MAX_BODY_BYTES) || 10 * 1024 * 1024;

function log(line) {
  console.log(`${new Date().toISOString()} [activator] ${line}`);
}

async function nomadGet(p) {
  const res = await fetch(`${NOMAD_ADDR}${p}`);
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Nomad ${p} -> ${res.status}`);
  return res.json();
}

// ---------------------------------------------------------------------
// Waking
// ---------------------------------------------------------------------

async function jobIsRunning(appName) {
  const job = await nomadGet(`/v1/job/${encodeURIComponent(appName)}`);
  return Boolean(job) && job.Status === 'running' && job.Stop !== true;
}

/**
 * Compare the app's data directory against the manifest idle-report.js
 * wrote when it stopped the app, and refuse to start if they disagree.
 *
 * This is the single most important function in this file. An app that
 * wakes up to a missing or empty database does not crash — SQLite (and
 * most app code) simply creates a fresh one, the app reports itself
 * perfectly healthy, and the user's data is gone with nothing to
 * indicate it. By the time anyone notices, the new empty database has
 * been written over the old one's place for hours.
 *
 * So the check runs BEFORE `nomad job run`, not after: once the app is
 * up it starts writing, and the evidence of what was lost goes with it.
 * A mismatch is a hard 503 and a loud log, never a "start it anyway".
 *
 * Sizes, not checksums: the files are quiescent between the stop and the
 * wake, so nothing should have changed at all. A size difference is
 * enough to catch truncation, deletion and a half-finished copy, without
 * reading a gigabyte of database on every cold start.
 */
async function verifyDataAgainstManifest(appName) {
  const manifestPath = `${appDataPathFor('.snapshots')}/${appName}/latest-manifest.json`;
  let manifest;
  try {
    manifest = JSON.parse(await fsp.readFile(manifestPath, 'utf8'));
  } catch (e) {
    if (e.code === 'ENOENT') {
      // No manifest means this app was never stopped BY US — someone
      // stopped it by hand, or it predates the snapshot. There is
      // nothing to compare against, so there is also nothing to
      // contradict. Proceed, but say so: a wake with no integrity check
      // is exactly the case worth being able to find in a log later.
      log(`${appName}: no manifest at ${manifestPath} — waking WITHOUT an integrity check`);
      return;
    }
    throw e;
  }

  const dataDir = appDataPathFor(appName);
  const actual = new Map();
  let entries;
  try {
    entries = await fsp.readdir(dataDir, { withFileTypes: true, recursive: true });
  } catch (e) {
    throw new Error(
      `data directory ${dataDir} is unreadable (${e.code}) but the manifest lists ` +
        `${manifest.fileCount} file(s) — refusing to start an app that would create a fresh, empty one`
    );
  }
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    const full = `${entry.parentPath || entry.path}/${entry.name}`;
    const stat = await fsp.stat(full);
    actual.set(full.slice(dataDir.length + 1), stat.size);
  }

  const problems = [];
  for (const f of manifest.files) {
    if (!actual.has(f.path)) {
      problems.push(`missing: ${f.path} (was ${f.bytes} bytes)`);
    } else if (actual.get(f.path) !== f.bytes) {
      problems.push(`size changed: ${f.path} ${f.bytes} -> ${actual.get(f.path)}`);
    }
  }
  // Extra files are reported but are NOT a failure on their own: nothing
  // here deletes, and a stray file cannot destroy data the way a missing
  // or truncated one can.
  for (const p of actual.keys()) {
    if (!manifest.files.some((f) => f.path === p)) log(`${appName}: note — extra file not in manifest: ${p}`);
  }

  if (problems.length > 0) {
    throw new Error(
      `DATA INTEGRITY CHECK FAILED for ${appName} against ${manifestPath}: ${problems.join('; ')}`
    );
  }
  log(`${appName}: data verified against manifest (${manifest.fileCount} file(s), ${manifest.totalBytes} bytes)`);
}

/**
 * Re-register the job from the spec idle-report.js saved before stopping.
 *
 * From the FILE, not from Nomad: `job_gc_threshold` (4h) removes a
 * stopped job from Nomad's state entirely, and an app is far more likely
 * to be woken after a long idle period than a short one — the GC'd case
 * is the normal case here, not the edge case.
 */
async function runSavedSpec(appName) {
  const specPath = `${appDataPathFor('.specs')}/${appName}.json`;
  await fsp.access(specPath).catch(() => {
    throw new Error(`no saved job spec at ${specPath} — cannot wake ${appName}`);
  });
  // -detach matters. Without it `nomad job run` MONITORS the deployment
  // and does not return until it has completed, so the activator would
  // sit blocked on the CLI while the thing it actually cares about — an
  // address to forward to — became available much earlier. It also made
  // a cold start look like a hang: nothing is logged for the whole
  // monitoring period, and a visitor gave up long before the request was
  // ever forwarded.
  //
  // waitForAddress below is the real wait, and it is the right one: it
  // polls the same service registry Traefik reads, at 500ms, and returns
  // the moment there is somewhere to send the request.
  //
  // Check the images BEFORE submitting. Nomad's failure mode for a
  // missing local image is to retry the pull, exhaust its restart
  // attempts and fail the deployment minutes later, reporting `pull
  // access denied ... repository does not exist` — which reads as a
  // registry auth problem and is nothing of the sort. idle-report.js now
  // refuses to stop an app in this state, so this should be
  // unreachable; it is here because "should be unreachable" is exactly
  // what was assumed about the image surviving a stop.
  const spec = JSON.parse(await fsp.readFile(specPath, 'utf8'));
  const missing = await missingImages(imagesFromSpec(spec));
  if (missing.length > 0) {
    throw new Error(
      `image(s) missing on this host: ${missing.join(', ')} — these are built locally and pushed to no ` +
        `registry, so ${appName} cannot be started without redeploying it`
    );
  }

  // `nomad job inspect` writes {"Job": {...}}, which `job run -json`
  // reads back directly.
  await execFileAsync('nomad', ['job', 'run', '-detach', '-json', specPath]);
}

/**
 * Wait until Nomad's service registry has an address for the app. This
 * is the same registry Traefik's Nomad provider reads, so an entry here
 * means both that we have somewhere to forward to AND that Traefik is
 * about to route directly and stop involving this process.
 */
async function waitForAddress(appName, deadline) {
  for (;;) {
    const regs = await nomadGet(`/v1/service/${encodeURIComponent(appName)}`).catch(() => null);
    if (Array.isArray(regs) && regs.length > 0 && regs[0].Address && regs[0].Port) {
      return { host: regs[0].Address, port: regs[0].Port };
    }
    if (Date.now() > deadline) throw new Error(`timed out waiting for ${appName} to register an address`);
    await new Promise((r) => setTimeout(r, 500));
  }
}

// Single-flight. A cold start takes tens of seconds, and a page load is
// a dozen parallel requests — without this, each one would fire its own
// `nomad job run`. Step 4's checklist tests exactly this.
const inFlight = new Map();

function ensureAwake(appName) {
  const existing = inFlight.get(appName);
  if (existing) return existing;
  const p = wake(appName).finally(() => inFlight.delete(appName));
  inFlight.set(appName, p);
  return p;
}

async function wake(appName) {
  const deadline = Date.now() + WAKE_TIMEOUT_MS;

  if (await jobIsRunning(appName)) {
    // Already up — a request that raced Traefik noticing. Nothing to
    // start, and no integrity check: the app is running and writing, so
    // the manifest is legitimately out of date by now.
    return waitForAddress(appName, deadline);
  }

  // Logged phase by phase, not just at the ends. A cold start is the one
  // path here that legitimately takes tens of seconds, so "no output yet"
  // and "wedged" look identical from outside — and that is exactly how
  // the blocking `nomad job run` above went unnoticed.
  const t0 = Date.now();
  log(`${appName}: cold start requested`);
  await verifyDataAgainstManifest(appName);
  await runSavedSpec(appName);
  log(`${appName}: job submitted (+${Date.now() - t0}ms), waiting for an address`);
  const addr = await waitForAddress(appName, deadline);
  log(`${appName}: awake at ${addr.host}:${addr.port} (+${Date.now() - t0}ms)`);
  return addr;
}

// ---------------------------------------------------------------------
// Proxying
// ---------------------------------------------------------------------

function appNameFromHost(hostHeader) {
  const host = String(hostHeader || '').split(':')[0].toLowerCase();
  // Matched against each app's own canonical domain rather than parsed
  // out of the hostname: it is the same helper that generated the
  // Traefik rule, so the two cannot drift.
  return WAKEABLE_APPS.find((name) => defaultDomainFor(name) === host) || null;
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (c) => {
      size += c.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error('request body too large to buffer during cold start'));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

function forward(req, res, addr, body) {
  return new Promise((resolve, reject) => {
    const headers = { ...req.headers };
    // Host is left exactly as the visitor sent it — the app may route on
    // it. Hop-by-hop headers are not ours to pass along.
    delete headers.connection;
    delete headers['keep-alive'];
    delete headers['transfer-encoding'];
    if (body.length > 0) headers['content-length'] = String(body.length);

    const upstream = http.request(
      { host: addr.host, port: addr.port, method: req.method, path: req.url, headers },
      (upRes) => {
        res.writeHead(upRes.statusCode, upRes.headers);
        upRes.pipe(res);
        upRes.on('end', resolve);
        upRes.on('error', reject);
      }
    );
    upstream.on('error', reject);
    upstream.end(body);
  });
}

/**
 * The app has registered an address, but "registered" is not "listening"
 * — Nomad registers the service as soon as the task starts, while the
 * process inside is still booting. Retrying the connection IS the
 * readiness check, which avoids guessing at a health endpoint that
 * every app defines differently (or not at all).
 *
 * Only a connection-level failure is retried, and only before any
 * response has begun: at that point nothing has been sent upstream, so
 * replaying a POST cannot duplicate anything the app has acted on.
 */
async function forwardWhenReady(req, res, addr, body, deadline) {
  for (;;) {
    try {
      return await forward(req, res, addr, body);
    } catch (e) {
      const retryable = ['ECONNREFUSED', 'ECONNRESET', 'EHOSTUNREACH'].includes(e.code);
      if (!retryable || Date.now() > deadline || res.headersSent) throw e;
      await new Promise((r) => setTimeout(r, 400));
    }
  }
}

const server = http.createServer(async (req, res) => {
  const appName = appNameFromHost(req.headers.host);
  if (!appName) {
    // Nothing should ever reach here: Traefik only routes hostnames that
    // have a fallback router in dynamic.yml. A 404 rather than a proxy
    // attempt means a misconfiguration can never turn this process into
    // an open relay for an arbitrary Host header.
    res.writeHead(404, { 'content-type': 'text/plain' });
    res.end('Not found\n');
    return;
  }

  const started = Date.now();
  // A visitor who gives up mid-cold-start (or a curl that is Ctrl-C'd)
  // is not a failure of this component, but it produces a write-to-dead-
  // socket error that reads exactly like one. Tracked so the log says
  // which happened.
  let clientGone = false;
  req.on('aborted', () => {
    clientGone = true;
  });
  res.on('close', () => {
    if (!res.writableFinished) clientGone = true;
  });

  try {
    const body = await readBody(req);
    const addr = await ensureAwake(appName);
    await forwardWhenReady(req, res, addr, body, started + WAKE_TIMEOUT_MS);
    log(`${appName}: ${req.method} ${req.url} served in ${Date.now() - started}ms`);
  } catch (e) {
    if (clientGone) {
      log(`${appName}: client disconnected after ${Date.now() - started}ms during ${req.method} ${req.url} (the wake itself continues)`);
      return;
    }
    log(`${appName}: FAILED ${req.method} ${req.url} after ${Date.now() - started}ms — ${e.message}`);
    if (res.headersSent) {
      res.destroy();
      return;
    }
    // A clean error after a bounded wait, never a hang: Step 4's
    // checklist requires an app that cannot start to produce this rather
    // than holding the visitor's connection open indefinitely.
    res.writeHead(503, { 'content-type': 'text/plain', 'retry-after': '30' });
    res.end('This app is starting up and did not become ready in time. Please try again.\n');
  }
});

// Longer than WAKE_TIMEOUT_MS: the whole point is to hold the connection
// through a cold start, and Node's 2-minute default would otherwise cut
// the visitor off before our own timeout had a chance to answer cleanly.
server.requestTimeout = WAKE_TIMEOUT_MS + 30000;
server.headersTimeout = WAKE_TIMEOUT_MS + 30000;

server.listen(PORT, '127.0.0.1', () => {
  log(`listening on 127.0.0.1:${PORT}, wakeable: ${WAKEABLE_APPS.join(', ')}`);
});
